$(window).load(function() {
  var body = $("body"),
      universe = $("#universe"),
      solarsys = $("#solar-system");

  var init = function() {
      // Start with 2D view and ensure images are visible
      body.removeClass('opening')
          .addClass("view-2D")  // Add 2D view class
          .delay(2000)
          .queue(function() {
              $(this).removeClass('hide-UI')
                  .addClass("set-speed");
              $(this).dequeue();
          });
      
      // Ensure all planets are visible initially
      $(".planet, .orbit").css({
          'visibility': 'visible',
          'opacity': 1
      });
  };

  var setView = function(view) {
      universe.removeClass().addClass(view);
      // Ensure elements stay visible when view changes
      $(".planet, .orbit").css({
          'visibility': 'visible',
          'opacity': 1
      });
  };

  // Toggle data panel
  $("#toggle-data").click(function(e) {
      body.toggleClass("data-open data-close");
      e.preventDefault();
  });

  // Toggle controls panel
  $("#toggle-controls").click(function(e) {
      body.toggleClass("controls-open controls-close");
      e.preventDefault();
  });

  // Handle planet selection with improved visibility
  $("#data a").click(function(e) {
      var ref = $(this).attr("class");
      solarsys.removeClass().addClass(ref);
      $(this).parent().find('a').removeClass('active');
      $(this).addClass('active');
      
      // Ensure selected planet and its orbit are visible
      $(".planet, .orbit").css({
          'visibility': 'visible',
          'opacity': 1
      });
      
      e.preventDefault();
  });

  // View controls with visibility maintenance
  $(".set-zoom").click(function() { 
      body.toggleClass("zoom-large zoom-close");
      // Ensure visibility after zoom
      $(".planet, .orbit").css({
          'visibility': 'visible',
          'opacity': 1
      });
  });
  
  $(".set-speed").click(function() { 
      setView("scale-stretched set-speed");
  });
  
  $(".set-size").click(function() { 
      setView("scale-s set-size");
  });
  
  $(".set-distance").click(function() { 
      setView("scale-d set-distance");
  });

  init();
});